<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
rh24_require_login();
$requested=trim((string)($_GET['state_code']??''));$scope=rh24_territory_book_scope($requested);$code=(string)($scope['state_code']??'');
if($code===''){http_response_code(403);exit('Kein Gebietsbuch zugeordnet.');}
$rows=rh24_territory_directory_rows($code,false);$cats=rh24_territory_directory_categories();$active=array_values(array_filter($rows,fn($r)=>($r['status']??'')==='active'));$groups=[];foreach($active as $r)$groups[$r['category']][]=$r;
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($scope['territory_book_no'])?> Gebietsbuch</title><style>
