</style></head><body><div class="bar"><b>Gebietsbuch · PDF / Druckansicht</b><button onclick="window.print()">Drucken / als PDF speichern</button></div><main class="sheet"><div class="head"><div><small>RÄUCHERHAKEN24 · FESTGEBIET</small><h1><?=h($scope['territory_book_no'])?> · <?=h($scope['state_name'])?></h1><div class="muted">Aktive Geschäfte, Vereine und Branchenkontakte</div></div><div class="meta"><b><?=count($active)?> aktive Adressen</b><br><?=h(date('d.m.Y H:i'))?></div></div><div class="summary"><div><b><?=count($active)?></b>Aktiv</div><div><b><?=count($groups)?></b>Branchen</div><div><b><?=h($scope['sales_rep_name']?:'nicht vergeben')?></b>Gebietsinhaber</div></div><?php foreach($groups as $cat=>$list):?><section class="group"><h2><?=h($cats[$cat]??$cat)?> · <?=count($list)?></h2><?php foreach($list as $r):?><div class="row"><div><b><?=h($r['company'])?></b><br><?=h($r['contact_person']??'')?></div><div><?=h($r['street']??'')?><br><b><?=h(($r['zip']??'').' '.($r['city']??''))?></b></div><div><?=h($r['phone']??'–')?><?=!empty($r['mobile'])?'<br>Mobil: '.h($r['mobile']):''?><br><?=h($r['email']??'–')?></div><div>Letzter Kontakt: <?=h($r['last_contacted_at']?date('d.m.Y H:i',strtotime($r['last_contacted_at'])):'–')?><br>Wiedervorlage: <?=h($r['next_follow_up_at']?date('d.m.Y H:i',strtotime($r['next_follow_up_at'])):'–')?></div></div><?php endforeach;?></section><?php endforeach;?><div class="foot">Interne Vertriebsunterlage · Räucherhaken24. Automatisch importierte Daten werden erst nach Prüfung als aktiv geführt. OSM-basierte Recherchedaten: © OpenStreetMap-Mitwirkende.</div></main></body></html>